#include <bits/stdc++.h>
using namespace std;

constexpr long long MOD = 1000000007;

long long count_sets(const vector<vector<int>>& adj) {
    int n = static_cast<int>(adj.size()) - 1;
    vector<int> par(n + 1), order, pending{1};
    order.reserve(n);
    while (!pending.empty()) {
        int vertex = pending.back();
        pending.pop_back();
        order.push_back(vertex);
        for (int next : adj[vertex]) {
            if (next != par[vertex]) {
                par[next] = vertex;
                pending.push_back(next);
            }
        }
    }

vector<long long> omitted(n + 1, 1), selected(n + 1, 1);
for (int i = n - 1; i >= 0; --i) {
    int vertex = order[i];
    for (int child : adj[vertex]) {
        if (child == par[vertex]) {
            continue;
        }
        omitted[vertex] = omitted[vertex]
            * ((omitted[child] + selected[child]) % MOD) % MOD;
        selected[vertex] = selected[vertex] * omitted[child] % MOD;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> adj(n + 1);
    for (int edge = 0; edge < n - 1; ++edge) {
        int first, second;
        cin >> first >> second;
        adj[first].push_back(second);
        adj[second].push_back(first);
    }
    cout << count_sets(adj) << '\n';
}

